  const discountType = input?.discountType === "percent" ? "percent" : "fixed";
  const discountValue = Math.max(0, Math.trunc(Number(input?.discountValue) || 0));
  if (!name) throw new Error("กรุณาระบุชื่อโปรโมชั่น");
