  const form = document.querySelector('form');
  const input = document.querySelector('#pin');
  const dots = Array.from(document.querySelectorAll('.dot'));
  const update = () => dots.forEach((dot, index) => dot.classList.toggle('filled', index < input.value.length));
  const add = value => { if (input.value.length < 6) { input.value += value; update(); if (input.value.length === 6) setTimeout(() => form.requestSubmit(), 120); } };
  document.querySelectorAll('[data-key]').forEach(button => button.addEventListener('click', () => add(button.dataset.key)));
